\section{Introduction}

\subsection{The problem}
The Bekenstein--Hawking formula $S=A/4$ assigns to a black hole horizon an entropy
proportional to its area. Boltzmann's identification $S=\log\Omega$ then demands a
count: roughly $e^{A/4}$ microstates for a horizon of area $A$. Any candidate
quantum theory of gravity is expected to supply that count, reproducing both the
linear dependence on $A$ and the coefficient $1/4$.

The isolated-horizon programme provides a concrete combinatorial answer. The
horizon is modelled as a two-sphere punctured by finitely many spin-network edges;
each puncture carries an $SU(2)$ spin $j$, contributes a quantum of area determined
by $j$, and carries $2j+1$ internal magnetic states. We work with the
\emph{equidistant} (large-spin, $k$-linear) area spectrum, in which a puncture of
label $k=2j$ contributes exactly $k$ elementary quanta of area. This is the regime
in which the counting problem is exactly solvable and in which the free area
quantum (the analogue of the Barbero--Immirzi parameter) is normally fixed.

\subsection{Contributions}
We give (i) an \emph{exact} solution of the counting problem, (ii) a
\emph{structural} theory identifying which features are model-independent, (iii) a
\emph{quantitative} treatment of the physical Gauss constraint, and (iv) a complete
\emph{thermodynamic} analysis with exact pole orders and residues at the Hagedorn
point. Every statement below is an identity, an inequality with explicit constants,
or an exact limit.

\section{The microstate model}

\begin{definition}[Puncture labels]
For $k\in\mathbb{N}$ set
$\mathcal{L}(k):=\{k-2i:0\le i\le k\}=\{k,k-2,\dots,-k\}\subset\mathbb{Z}$.
These are the doubled magnetic numbers $M=2m$ of a spin-$j$ puncture with $k=2j$:
integers of the same parity as $k$ with $\lvert M\rvert\le k$. Since $i\mapsto k-2i$
is injective, $\lvert\mathcal{L}(k)\rvert=k+1$, the degeneracy $2j+1$.
\end{definition}

\begin{definition}[Horizon configuration]
A \emph{horizon configuration} is a finite ordered list
$\ell=((k_1,M_1),\dots,(k_N,M_N))$ with $k_i\ge1$ and $M_i\in\mathcal{L}(k_i)$. Its
\emph{area} is $\ar(\ell):=\sum_i k_i$ and its \emph{projection} is
$\pr(\ell):=\sum_i M_i$. Punctures are ordered, being attached to distinguishable
spin-network edges.
\end{definition}

\begin{definition}[Microstate count]
Let $\mathcal{H}(A)$ be the finite set of horizon configurations of area $A$ and
$\Wc(A):=\lvert\mathcal{H}(A)\rvert$. Equivalently $\mathcal{H}(0)=\{()\}$ and
\[
\mathcal{H}(A+1)=\bigsqcup_{i=0}^{A}\ \bigsqcup_{M\in\mathcal{L}(i+1)}
\bigl\{(i+1,M)::\ell\ :\ \ell\in\mathcal{H}(A-i)\bigr\},
\]
the union being disjoint because the head of the list determines $(i,M)$.
\end{definition}

Small values: $\Wc(0)=1$, $\Wc(1)=2$, $\Wc(2)=7$, $\Wc(3)=24$, $\Wc(4)=82$,
$\Wc(5)=280$, $\Wc(6)=956$, $\Wc(7)=3264$, $\Wc(8)=11144$, $\Wc(9)=38048$.

\begin{definition}
The microcanonical entropy is $S(A):=\log \Wc(A)$ and the entropy density is
$\lambda:=\log(2+\sqrt2)$.
\end{definition}

\section{Exact solution of the counting problem}

\begin{proposition}[Renewal recursion]\label{prop:renewal}
For every $A\ge0$,
\[
\Wc(A+1)=\sum_{i=0}^{A}(i+2)\,\Wc(A-i)=\sum_{j=0}^{A}(A-j+2)\,\Wc(j).
\]
\end{proposition}

\begin{proof}[Proof sketch]
Split $\mathcal{H}(A+1)$ by the label $i+1$ and magnetic number $M$ of the first
puncture. The fibre over $(i,M)$ is the injective image of $\mathcal{H}(A-i)$ under
$\ell\mapsto(i+1,M)::\ell$, so it has $\Wc(A-i)$ elements, and there are
$\lvert\mathcal{L}(i+1)\rvert=i+2$ choices of $M$. Reindexing $j=A-i$ gives the
second form.
\end{proof}

\begin{lemma}[Three-term form]\label{lem:threeterm}
For every $A\ge1$, $\displaystyle \Wc(A+1)=3\Wc(A)+\sum_{j=0}^{A-1}\Wc(j)$.
\end{lemma}

\begin{proof}[Proof sketch]
Write $A=m+1$. In $\Wc(A+1)=\sum_{j\le A}(A-j+2)\Wc(j)$ isolate the top term $j=A$,
contributing $2\Wc(A)$. For $j\le m$ use $(m+1-j+2)=(m-j+2)+1$, so the remaining sum
splits as $\sum_{j\le m}(m-j+2)\Wc(j)+\sum_{j\le m}\Wc(j)=\Wc(m+1)+\sum_{j\le m}\Wc(j)$
by Proposition~\ref{prop:renewal} at $m$. Recombining gives the claim.
\end{proof}

\begin{theorem}[Finite linear recursion]\label{thm:linrec}
For every $A\ge1$, $\ \Wc(A+2)+2\Wc(A)=4\Wc(A+1)$.
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:threeterm} at $A$ and $A+1$, writing $\Sigma_n=\sum_{j\le n}\Wc(j)$:
$\Wc(A+1)=3\Wc(A)+\Sigma_{A-1}$ and $\Wc(A+2)=3\Wc(A+1)+\Sigma_A$. Since
$\Sigma_A=\Sigma_{A-1}+\Wc(A)$, subtraction gives
$\Wc(A+2)=3\Wc(A+1)+\bigl(\Wc(A+1)-3\Wc(A)\bigr)+\Wc(A)=4\Wc(A+1)-2\Wc(A)$.
\end{proof}

\begin{remark}
The collapse from infinite to finite order reflects rationality of the degeneracy
generating function: $\sum_{k\ge1}(k+1)x^k=(1-x)^{-2}-1$, so the renewal identity
$\widehat{\Wc}(x)=\bigl(1-\sum_k\deg(k)x^k\bigr)^{-1}$ has denominator of degree two.
Theorem~\ref{thm:linrec} is that fact proved combinatorially.
\end{remark}

Let $s:=2+\sqrt2$ and $s':=2-\sqrt2$ be the roots of $x^2-4x+2$, so $s+s'=4$,
$ss'=2$, $s^2=4s-2$, $s'^2=4s'-2$, and $0<s'<1<s$.

\begin{theorem}[Exact closed form]\label{thm:closed}
For every $A\ge1$, $\ 4\Wc(A)=(1+\sqrt2)\,s^A+(1-\sqrt2)\,s'^A$.
\end{theorem}

\begin{proof}[Proof sketch]
Both sides satisfy the same order-two recursion for $A\ge1$, so it suffices to
check $A=1,2$. At $A=1$: $(1+\sqrt2)(2+\sqrt2)+(1-\sqrt2)(2-\sqrt2)=(4+3\sqrt2)+(4-3\sqrt2)=8=4\Wc(1)$.
At $A=2$: $(1+\sqrt2)(6+4\sqrt2)+(1-\sqrt2)(6-4\sqrt2)=28=4\Wc(2)$. A two-step
induction carrying consecutive pairs then closes. The hypothesis $A\ge1$ is
necessary: the right-hand side at $A=0$ equals $2$, whereas $4\Wc(0)=4$.
\end{proof}

\begin{corollary}[Two-sided bound]\label{cor:bounds}
For $A\ge1$, $\ s^A/2\le \Wc(A)\le s^A$.
\end{corollary}

\begin{proof}[Proof sketch]
Use $1<\sqrt2<2$, $1+\sqrt2<4$ and $0<s'^A\le s^A$ in Theorem~\ref{thm:closed}:
$4\Wc(A)\le(1+\sqrt2)s^A\le 4s^A$ and
$4\Wc(A)\ge(1+\sqrt2)s^A-(\sqrt2-1)s^A=2s^A$.
\end{proof}

\section{The area law and the area quantum}

\begin{theorem}[Area law with bounded defect]\label{thm:arealaw}
For every $A\ge1$, $\ \lvert S(A)-A\lambda\rvert\le\log2$ with $\lambda=\log(2+\sqrt2)$.
\end{theorem}

\begin{proof}
Take logarithms in Corollary~\ref{cor:bounds}.
\end{proof}

\begin{theorem}[Bekenstein--Hawking area law]
$\displaystyle \lim_{A\to\infty}\frac{S(A)}{A}=\lambda=\log(2+\sqrt2)\approx1.227947.$
\end{theorem}

\begin{proof}
$\lvert S(A)/A-\lambda\rvert\le(\log2)/A\to0$.
\end{proof}

Put $\theta:=s'/s=(2-\sqrt2)/(2+\sqrt2)=3-2\sqrt2\approx0.171573$.

\begin{proposition}\label{prop:ratio}
For $A\ge1$,
\[
\frac{\Wc(A)}{s^A}=\frac{1+\sqrt2}{4}+\frac{1-\sqrt2}{4}\,\theta^A,
\qquad
\Bigl\lvert\frac{\Wc(A)}{s^A}-\frac{1+\sqrt2}{4}\Bigr\rvert\le\frac{\sqrt2-1}{4}\,\theta^A.
\]
\end{proposition}

\begin{theorem}[No logarithmic correction]
$\displaystyle S(A)-A\lambda\longrightarrow\log\frac{1+\sqrt2}{4}\approx-0.504921$,
exponentially fast with ratio $\theta$.
\end{theorem}

\begin{proof}
$S(A)-A\lambda=\log\bigl(\Wc(A)/s^A\bigr)$; apply Proposition~\ref{prop:ratio} and
continuity of $\log$ at $(1+\sqrt2)/4>0$.
\end{proof}

Thus the \emph{unconstrained} ensemble has no logarithmic correction: the subleading
term is an explicit constant. Any $-\tfrac12\log A$ in the physical entropy must
originate in the projection constraint (Section~\ref{sec:gauss}).

\begin{theorem}[Uniqueness of the Bekenstein--Hawking normalisation]
Let the physical area be $A_{\mathrm{phys}}=\gamma A$ with $\gamma>0$. Then
\[
\lim_{A\to\infty}\frac{S(A)}{\gamma A}=\frac14
\quad\Longleftrightarrow\quad
\gamma=4\lambda=4\log(2+\sqrt2)\approx4.911788 .
\]
\end{theorem}

\begin{theorem}[Isolated-horizon characteristic equation]\label{thm:chareq}
With $x_c:=1/(2+\sqrt2)=1-\tfrac{\sqrt2}{2}\approx0.292893$,
$\ \sum_{k\ge1}(k+1)x_c^{\,k}=1$.
\end{theorem}

\begin{proof}[Proof sketch]
For $0<x<1$, $\sum_{k\ge0}(k+1)x^k=(1-x)^{-2}$, so $\sum_{k\ge1}(k+1)x^k=(1-x)^{-2}-1$.
Setting this to $1$ gives $(1-x)^2=\tfrac12$, i.e.\ $x=1-\tfrac{\sqrt2}{2}=1/(2+\sqrt2)$.
\end{proof}

\section{Universality: an arbitrary puncture model}

\begin{definition}
Let $\deg:\mathbb{N}\to\mathbb{N}$ assign to each area $k\ge1$ the number $\deg(k)$
of internal states of a puncture of area $k$. A \emph{generalised configuration} is
a finite list $((k_1,a_1),\dots,(k_N,a_N))$ with $k_i\ge1$ and $0\le a_i<\deg(k_i)$;
its area is $\sum_i k_i$. Let $\Wc_{\deg}(A)$ count these. Standing hypotheses:
$\deg(1)\ge1$ and $\deg(k)\le B^k$ for some $B\in\mathbb{N}$. The concrete model is
$\deg(k)=k+1$, for which $\Wc_{\deg}=\Wc$.
\end{definition}

\begin{lemma}[Supermultiplicativity]\label{lem:supermul}
$\Wc_{\deg}(n)\Wc_{\deg}(m)\le \Wc_{\deg}(n+m)$.
\end{lemma}

\begin{proof}[Proof sketch]
Concatenation is injective: the area $n$ of the first factor determines the cut.
\end{proof}

\begin{lemma}\label{lem:elembounds}
$\deg(1)^A\le \Wc_{\deg}(A)\le(2B)^A$.
\end{lemma}

\begin{proof}[Proof sketch]
Lower: the $\deg(1)^A$ lists of $A$ minimal punctures. Upper: a configuration is a
composition of $A$ (at most $2^{A-1}$) plus internal labels (at most
$\prod_i B^{k_i}=B^A$).
\end{proof}

\begin{theorem}[Universal area law]
The limit $L:=\lim_{A\to\infty}\log \Wc_{\deg}(A)/A$ exists, is finite, and satisfies
$\log\deg(1)\le L\le\log(2B)$.
\end{theorem}

\begin{proof}[Proof sketch]
$-\log \Wc_{\deg}$ is subadditive by Lemma~\ref{lem:supermul} and linearly bounded
below by Lemma~\ref{lem:elembounds}; Fekete's subadditive lemma gives convergence to
$\sup_A\log \Wc_{\deg}(A)/A$.
\end{proof}

For $\deg(k)=k+1$ this recovers $L=\lambda$, and with $B=2$ the bracket reads
$\log2\le\log(2+\sqrt2)\le\log4$.

\begin{definition}
The \emph{characteristic function} is $f(x):=\sum_{k\ge1}\deg(k)x^k$, and a
\emph{characteristic root} is a positive $r$ with $f(r)=1$. For finitely supported
models $f$ is a strictly increasing polynomial with $f(0)=0$ and $f(1)\ge\deg(1)\ge1$,
so the root exists, lies in $(0,1]$, and is unique.
\end{definition}

\begin{theorem}[Characteristic-root theorem]\label{thm:charroot}
If $r>0$ satisfies $\sum_{k\ge1}\deg(k)r^k=1$, then $L=-\log r$. No finite-support
hypothesis is required.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Upper bound.} Strong induction on the renewal recursion: if
$\Wc_{\deg}(A-k)\le r^{-(A-k)}$ for all $k$, then
$\Wc_{\deg}(A)=\sum_k\deg(k)\Wc_{\deg}(A-k)\le r^{-A}\sum_k\deg(k)r^k=r^{-A}$. The
characteristic equation is exactly what closes the induction; only partial sums are
used, so this half needs no finite support.

\emph{Lower bound.} Set $m(A):=\Wc_{\deg}(A)r^A$, so $m(0)=1$, $m\le1$, and
$m(A)=\sum_{k\ge1}p_k\,m(A-k)$ with $p_k:=\deg(k)r^k\ge0$, $\sum_k p_k=1$. Each
value is a convex average of earlier values, so the running minimum is
nonincreasing; with $p_1=\deg(1)r\ge r>0$ this yields a uniform bound $m(A)\ge c>0$.
Squeezing $\log m(A)/A$ between $\log c/A$ and $0$ gives $L=-\log r$.

\emph{Infinite support.} Truncate to $\deg_K$ with root $r_K$ and density $L_K$. For
$x>r$ the truncated characteristic polynomials eventually exceed $1$ (either the
series converges at $x$ and strict termwise comparison gives $f(x)>f(r)=1$, or it
diverges and its partial sums tend to $\infty$). Hence $r_K\downarrow r$; squeezing
$L_K\le L\le-\log r$ gives $L=-\log r$.
\end{proof}

\begin{corollary}
For the concrete model, any positive solution $y$ of $\sum_{k\ge1}(k+1)y^k=1$
satisfies $\lambda=-\log y$; with Theorem~\ref{thm:chareq}, $\lambda=\log(2+\sqrt2)$
intrinsically.
\end{corollary}

\begin{theorem}[Strict monotonicity: Barbero--Immirzi rigidity]\label{thm:rigid}
If $\deg\le\deg'$ pointwise with strict inequality somewhere, both satisfying the
standing hypotheses, then $L(\deg)<L(\deg')$.
\end{theorem}

\begin{proof}[Proof sketch]
A pointwise increase makes $f$ strictly larger at the root, so $r'<r$ and
$L'=-\log r'>-\log r=L$. For infinite support apply this to large truncations.
\end{proof}

Physically the area quantum $\gamma=4L$ is \emph{not} universal: it moves strictly
whenever the microscopic degeneracy spectrum changes.

\begin{lemma}[Finite certificate]\label{lem:cert}
If $\Wc_{\deg}(m)\ge2$ for some $m\ge1$, then $L\ge(\log2)/m>0$.
\end{lemma}

\begin{proof}[Proof sketch]
Iterating Lemma~\ref{lem:supermul} gives $\Wc_{\deg}(m)^n\le \Wc_{\deg}(nm)$, so
$\log \Wc_{\deg}(nm)/(nm)\ge(\log2)/m$; pass to the limit along $nm$.
\end{proof}

\begin{lemma}[The degenerate model]\label{lem:degen}
If $\deg(1)=1$ and $\deg(k)=0$ for $k\ge2$, the unique configuration of area $A$ is
the list of $A$ minimal punctures, so $\Wc_{\deg}\equiv1$ and $L=0$.
\end{lemma}

\begin{theorem}[Rigidity of the area law]
Under the standing hypotheses,
\[
L>0\iff\bigl(\deg(1)\ge2\ \text{ or }\ \exists k\ge2:\deg(k)\ge1\bigr),
\]
i.e.\ $L>0$ unless the model is the degenerate one of Lemma~\ref{lem:degen}. Every
non-degenerate model therefore obeys a two-sided extensive law
$cA\le\log \Wc_{\deg}(A)\le CA$ with $0<c\le C<\infty$: no sub-extensive entropy and
no volume law occurs in this class.
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) If $\deg(1)\ge2$ take $m=1$; if $\deg(k)\ge1$ for some $k\ge2$ take
$m=k$ and compare the single area-$k$ puncture with the list of $k$ minimal
punctures (distinct, having different lengths). Apply Lemma~\ref{lem:cert}.
($\Rightarrow$) Contrapositive is Lemma~\ref{lem:degen}.
\end{proof}

\begin{theorem}[Truncation rate]\label{thm:trunc}
Assume $\deg(k)\le B^k$ and $Br<1$, with $r$ the characteristic root. Then
$r\le r_K$ and
\[
0\le L-L_K\le\frac{B}{1-Br}\,(Br)^K .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The tail is geometric:
$1-\sum_{k\le K}\deg(k)r^k=\sum_{k>K}\deg(k)r^k\le(Br)^{K+1}/(1-Br)$. The linear
term of $f_K$, of coefficient $\deg(1)\ge1$, converts this into
$r_K-r\le(Br)^{K+1}/(1-Br)$; finally $L-L_K=\log(r_K/r)\le(r_K-r)/r$.
\end{proof}

\begin{corollary}
For $\deg(k)=k+1\le2^k$ ($B=2$, $r=x_c$, $Br=2-\sqrt2\approx0.5858$),
\[
0\le\lambda-L_K\le\frac{2}{1-2x_c}\,(2x_c)^K\approx4.83\times(0.5858)^K .
\]
Hence $\lambda$, and with it $\gamma=4\lambda$, is certified to accuracy
$\varepsilon$ by the finite model with $K=O(\log(1/\varepsilon))$ puncture types.
\end{corollary}

\section{The projection (Gauss) constraint}\label{sec:gauss}

Physically an admissible state must be a gauge singlet: $\pr(\ell)=0$.

\begin{definition}
Let $D(A,M):=\lvert\{\ell\in\mathcal{H}(A):\pr(\ell)=M\}\rvert$ be the
\emph{projection profile} and $Z(A):=D(A,0)$ the constrained count. Since
$\lvert\pr(\ell)\rvert\le\ar(\ell)$ we have $\Wc(A)=\sum_{M=-A}^{A}D(A,M)$.
\end{definition}

\begin{proposition}[Symmetry]
$D(A,-M)=D(A,M)$.
\end{proposition}

\begin{proof}[Proof sketch]
The puncturewise flip $(k,M)\mapsto(k,-M)$ is an involution of $\mathcal{H}(A)$
negating the projection.
\end{proof}

\begin{proposition}[Parity superselection]\label{prop:parity}
$Z(A)=0$ for odd $A$.
\end{proposition}

\begin{proof}[Proof sketch]
$M_i\equiv k_i\pmod2$, so $\pr(\ell)\equiv\ar(\ell)\pmod2$.
\end{proof}

\begin{proposition}[Summed concatenation injection]\label{prop:concat}
$\displaystyle \sum_{M=-A}^{A}D(A,M)^2\le Z(2A)$.
\end{proposition}

\begin{proof}[Proof sketch]
Gluing a configuration of area $A$ and projection $M$ to one of area $A$ and
projection $-M$ gives a constrained configuration of area $2A$. The map is injective
simultaneously over all $M$: the concatenation determines the cut after $A$ quanta,
hence both factors, and $M$ is the projection of the first.
\end{proof}

\begin{theorem}[Sharp constraint bound]\label{thm:sharp}
$\Wc(A)^2\le(2A+1)\,Z(2A)$.
\end{theorem}

\begin{proof}
Cauchy--Schwarz on the $(2A+1)$-term sum $\Wc(A)=\sum_{\lvert M\rvert\le A}D(A,M)$
combined with Proposition~\ref{prop:concat}.
\end{proof}

This improves by one power of $(2A+1)$ on the pigeonhole bound
$\Wc(A)^2\le(2A+1)^2Z(2A)$.

\begin{corollary}
For $A\ge1$,
\[
\frac{(2+\sqrt2)^{2A}}{4(2A+1)}\le Z(2A)\le(2+\sqrt2)^{2A},
\qquad
0\le 2A\lambda-\log Z(2A)\le\log4+\log(2A+1).
\]
Consequently $\log Z(2n)/(2n)\to\lambda$: the constrained entropy obeys the same
area law with the same density.
\end{corollary}

\begin{proposition}[Failure of unimodality]
At $A=1$, $D(1,\pm1)=1$ while $D(1,0)=Z(1)=0$ by Proposition~\ref{prop:parity}.
Hence $D(A,M)\le D(A,0)$ is false in general; unimodality can hold at best within a
parity class.
\end{proposition}

\section{Canonical thermodynamics}

\begin{theorem}[Ratio convergence and the differential law]
$\Wc(A+1)/\Wc(A)\to2+\sqrt2$, hence $S(A+1)-S(A)\to\log(2+\sqrt2)$. With the
normalisation $\gamma=4\log(2+\sqrt2)$ this reads
$dS/dA_{\mathrm{phys}}=\tfrac14$.
\end{theorem}

\begin{proof}[Proof sketch]
With $a=1+\sqrt2$, $b=1-\sqrt2$, $q=\theta$, Theorem~\ref{thm:closed} gives
$\Wc(A+1)/\Wc(A)=(as+bs'q^A)/(a+bq^A)\to s$.
\end{proof}

\begin{definition}
With fugacity $x=e^{-\beta}$ per area quantum, $\Zc(x):=\sum_{A\ge0}\Wc(A)x^A$.
\end{definition}

\begin{theorem}[Convergence and closed form]\label{thm:partition}
$\Zc(x)$ converges if and only if $x<x_c:=1/(2+\sqrt2)$, and for $0\le x<x_c$,
\[
\Zc(x)=\frac{(1-x)^2}{2x^2-4x+1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
$\Wc(A)\asymp s^A$ up to a factor $2$, so the radius of convergence is $1/s=x_c$;
at $x_c$ the terms satisfy $\Wc(A)x_c^A\ge\tfrac12$ and do not vanish. For the
closed form sum $4\Wc(A)=as^A+bs'^A$ against $x^A$ with two geometric series, or
use $\Zc(x)=\bigl(1-\sum_{k\ge1}(k+1)x^k\bigr)^{-1}=\bigl(2-(1-x)^{-2}\bigr)^{-1}$.
\end{proof}

Since $2x^2-4x+1$ vanishes at $1\pm\tfrac{\sqrt2}{2}$, $\Zc$ has a simple pole at
$x_c$: a Hagedorn transition with limiting temperature
\[
T_H=\frac{1}{\log(2+\sqrt2)}\approx0.814367
\]
per area quantum. Above $T_H$ the density of states outruns the Boltzmann
suppression and no equilibrium exists.

\begin{theorem}[Weighted sums in closed form]
For $0\le x<x_c$,
\[
\sum_A A\,\Wc(A)x^A=\frac{2x(1-x)}{(2x^2-4x+1)^2},\qquad
\sum_A A^2\,\Wc(A)x^A=\frac{2x(4x^3-6x^2+2x+1)}{(2x^2-4x+1)^3},
\]
\[
\sum_A A^3\,\Wc(A)x^A=\frac{2x(1+12x-20x^2+20x^4-16x^5)}{(2x^2-4x+1)^4}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Insert $4\Wc(A)=as^A+bs'^A$ and use $\sum n\rho^n=\rho/(1-\rho)^2$,
$\sum n^2\rho^n=\rho(1+\rho)/(1-\rho)^3$,
$\sum n^3\rho^n=\rho(1+4\rho+\rho^2)/(1-\rho)^4$ at $\rho=sx$ and $\rho=s'x$. The
cubic identity follows from the binomial transform
$\sum_n\binom{n+3}{3}\rho^n=(1-\rho)^{-4}$ and
$n^3=6\binom{n+3}{3}-12\binom{n+2}{2}+7n+6$. Combining branches with
$(1-sx)(1-s'x)=1-4x+2x^2$ gives the stated rational functions.
\end{proof}

\begin{theorem}[Cumulants in closed form]
For $0<x<x_c$,
\[
\kappa_1(x)=\frac{2x}{(2x^2-4x+1)(1-x)},\qquad
\kappa_2(x)=\frac{2x(4x^3-6x^2+1)}{(2x^2-4x+1)^2(1-x)^2},
\]
\[
\kappa_3(x)=\frac{2x(1+5x-36x^2+56x^3-4x^4-36x^5+16x^6)}{(2x^2-4x+1)^3(1-x)^3}.
\]
\end{theorem}

\begin{theorem}[Exact pole orders and residues]
As $x\uparrow x_c$,
\[
(x_c-x)\,\kappa_1(x)\to x_c,\qquad
(x_c-x)^2\,\kappa_2(x)\to x_c^2,\qquad
(x_c-x)^3\,\kappa_3(x)\to 2x_c^3=2!\,x_c^3 .
\]
Hence the poles have orders exactly $1$, $2$, $3$.
\end{theorem}

\begin{proof}[Proof sketch]
Factor $2x^2-4x+1=2(x-x_c)(x-x_+)$ with $x_+=1+\tfrac{\sqrt2}{2}$, so near $x_c$
this equals $2\sqrt2(x_c-x)(1+o(1))$, and $1-x_c=\tfrac{\sqrt2}{2}$. For $\kappa_1$
the denominator behaves like $2(x_c-x)$ and the numerator tends to $2x_c$. For
$\kappa_2$ one uses the algebraic identity $4x_c^3-6x_c^2-2x_c+1=0$, verified from
$x_c^2=\tfrac32-\sqrt2$ and $x_c^3=\tfrac52-\tfrac74\sqrt2$. The cubic case is
analogous.
\end{proof}

\begin{theorem}[Stability, skewness, and ensemble inequivalence]
For all $0<x<x_c$ one has $\kappa_2(x)>0$ and $\kappa_3(x)>0$: the specific heat
$C=\beta^2\kappa_2$ is strictly positive (the canonical horizon is stable below
$T_H$) and the area distribution is strictly right-skewed. Moreover
$\kappa_1(x)\to\infty$ and $\kappa_2(x)\to\infty$ as $x\uparrow x_c$, so no finite
horizon area can be prepared canonically near $T_H$, while the microcanonical
description is well defined at every area: the ensembles are inequivalent.
\end{theorem}

\begin{proof}[Proof sketch]
Positivity from the closed forms and $0<x<x_c$. Divergence either from the residues
above, or microcanonically: for each $M$,
$\kappa_1(x)\ge M\bigl(1-\Sigma_M(x)/\Zc(x)\bigr)$ with
$\Sigma_M(x)=\sum_{A<M}\Wc(A)x^A\le\Sigma_M(x_c)$ bounded and $\Zc(x)\to\infty$.
\end{proof}

The pattern $\kappa_m\sim(m-1)!\,x_c^m/(x_c-x)^m$ for $m=1,2,3$ is the cumulant
hierarchy of a geometric distribution with mean $x_c/(x_c-x)$: near criticality the
canonical area distribution becomes asymptotically exponential.

\section{Algorithms}

\textbf{(A) Exact microstate count.} Iterate $\Wc(A+2)=4\Wc(A+1)-2\Wc(A)$ from the
seed $\Wc(1)=2$, $\Wc(2)=7$ (the recursion is valid only from $A\ge1$). Cost $O(A)$
exact integer operations, $O(A^2)$ bit operations, versus $O(A^2)$ big-integer
operations for the renewal convolution.

\textbf{(B) Characteristic-root solver.} Bisect for the unique root of
$f_K(x)=\sum_{k\le K}\deg(k)x^k=1$ on $[\varepsilon,1]$; $f_K$ is strictly
increasing with $f_K(0)=0$, so bisection needs $O(\log(1/\varepsilon))$ evaluations
of cost $O(K)$. Return $L_K=-\log r_K$, with a rigorous error bar from
Theorem~\ref{thm:trunc}.

\textbf{(C) Cumulant evaluator.} Evaluate the rational closed forms directly, or
cross-check against truncated sums $\sum_A A^p\Wc(A)x^A$ computed with (A).

\section{Discussion}

The exact solution buys three things that asymptotic methods do not: a
\emph{uniform} error bound $\log2$ in the area law, valid at every area; an
\emph{identified} subleading term $\log\frac{1+\sqrt2}{4}$ approached at rate
$(3-2\sqrt2)^A$, which cleanly localises any $-\tfrac12\log A$ correction in the
Gauss constraint rather than in the counting; and exact pole orders and residues at
the Hagedorn point instead of fitted scaling exponents.

The universality results identify what survives beyond $\deg(k)=k+1$: an area law
always holds (supermultiplicativity plus an exponential ceiling); the density is
always the characteristic root; the density is strictly sensitive to the degeneracy
spectrum, so the Barbero--Immirzi parameter is a genuinely microscopic quantity; and
extensivity is generic, with a single degenerate model separating positive density
from triviality. What is \emph{not} universal is the collapse to a finite-order
recursion, which needs the degeneracy generating function to be rational.

Interpreting $x=e^{-\beta}$ per area quantum, the thermodynamic picture is coherent:
strictly positive specific heat below $T_H$, a double-pole divergence of the
specific heat and a simple-pole divergence of the mean area at $T_H$, and consequent
inequivalence of the microcanonical and canonical ensembles --- a feature shared with
realistic self-gravitating systems.

\section{Future directions}

\begin{enumerate}
\item \emph{Exact constrained asymptotics.} Prove or refute
$\log Z(2A)=2A\lambda-\tfrac12\log A+c+o(1)$ for an explicit $c$, via a local
central limit theorem for the projection profile.
\item \emph{Parity-restricted unimodality.} Prove $D(2A,M)\le D(2A,0)$ for even
areas, the corrected form of the refuted conjecture.
\item \emph{Higher cumulants.} Establish $\kappa_m(x)\sim(m-1)!\,x_c^m/(x_c-x)^m$
for all $m$; the cases $m=1,2,3$ are settled with residues $x_c$, $x_c^2$, $2x_c^3$.
\item \emph{Non-equidistant area spectra.} Replace $k$-linear area by the exact
$SU(2)$ spectrum $\propto\sqrt{j(j+1)}$; the characteristic-equation formulation
survives as a Laplace-transform criticality condition, but the recursion collapse
does not.
\item \emph{Truncation under saturated growth.} Determine the optimal truncation
rate when $\deg$ saturates the exponential ceiling and $Br\ge1$.
\item \emph{Two-sided rigidity.} Quantify the strict monotonicity of the density
into a stability estimate for the area quantum.
\item \emph{Finite-size Hagedorn crossover.} Impose a maximum spin and determine how
the pole at $x_c$ is smoothed into a finite-width crossover.
\end{enumerate}

\section{Summary of principal results}

\begin{longtable}{@{}p{0.33\textwidth}p{0.60\textwidth}@{}}
\toprule
\textbf{Result} & \textbf{Statement} \\
\midrule
\endhead
Renewal recursion & $\Wc(A+1)=\sum_{i\le A}(i+2)\Wc(A-i)$ \\
Finite linear recursion & $\Wc(A+2)=4\Wc(A+1)-2\Wc(A)$, $A\ge1$ \\
Closed form & $4\Wc(A)=(1+\sqrt2)(2+\sqrt2)^A+(1-\sqrt2)(2-\sqrt2)^A$ \\
Two-sided bound & $(2+\sqrt2)^A/2\le \Wc(A)\le(2+\sqrt2)^A$ \\
Area law & $\lvert\log \Wc(A)-A\log(2+\sqrt2)\rvert\le\log2$ \\
Subleading constant & $S(A)-A\log(2+\sqrt2)\to\log\frac{1+\sqrt2}{4}$, rate $(3-2\sqrt2)^A$ \\
Area quantum & $S/(\gamma A)\to\tfrac14\iff\gamma=4\log(2+\sqrt2)$ \\
Characteristic equation & $\sum_{k\ge1}(k+1)x^k=1$ at $x=1/(2+\sqrt2)$ \\
Universal area law & $L$ exists, $\log\deg(1)\le L\le\log 2B$ \\
Characteristic root & $\sum_k\deg(k)r^k=1\Rightarrow L=-\log r$ \\
Rigidity & $\deg\lneq\deg'\Rightarrow L(\deg)<L(\deg')$ \\
Positivity dichotomy & $L>0$ unless $\deg(1)=1$, $\deg(k\ge2)=0$ \\
Truncation rate & $0\le L-L_K\le\frac{B}{1-Br}(Br)^K$ \\
Constraint bound & $\Wc(A)^2\le(2A+1)Z(2A)$; defect $\le\log4+\log(2A+1)$ \\
Parity rule & $Z(A)=0$ for odd $A$; unimodality of $D(A,\cdot)$ is false \\
Differential law & $S(A+1)-S(A)\to\log(2+\sqrt2)$ \\
Partition function & converges iff $x<x_c$; $\Zc(x)=(1-x)^2/(2x^2-4x+1)$ \\
Hagedorn temperature & $T_H=1/\log(2+\sqrt2)\approx0.8144$ \\
Cumulant poles & orders $1,2,3$ with residues $x_c$, $x_c^2$, $2x_c^3$ \\
Stability & $\kappa_2,\kappa_3>0$ subcritically; both diverge at $x_c$ \\
Ensemble inequivalence & $\langle A\rangle\to\infty$ as $x\uparrow x_c$ \\
\bottomrule
\end{longtable}

