"""Brute-force verification that the recursion really counts horizon microstates.

Enumerates every ordered puncture configuration of small area, tabulates the
projection profile D(A, M), and checks against the closed-form and constrained
predictions:

  * W(A) enumerated == W(A) from W(A+2) = 4W(A+1) - 2W(A);
  * D(A, -M) = D(A, M)                            (magnetic-flip involution);
  * D(A, M) = 0 unless M and A have the same parity;
  * Z(A) := D(A, 0) = 0 for odd A                 (parity superselection);
  * sum_M D(A,M)^2 <= Z(2A)                       (concatenation injection);
  * W(A)^2 <= (2A+1) Z(2A)                        (sharp constraint bound).
"""

from __future__ import annotations
import math
from typing import Dict, Iterator, List, Tuple


def configurations(area: int) -> Iterator[Tuple[Tuple[int, int], ...]]:
    """All ordered lists ((k,M),...) with k>=1, M in {k,k-2,...,-k}, sum k = area."""
    if area == 0:
        yield ()
        return
    for k in range(1, area + 1):
        for i in range(k + 1):
            head = (k, k - 2 * i)
            for tail in configurations(area - k):
                yield (head,) + tail


def profile(area: int) -> Dict[int, int]:
    d: Dict[int, int] = {}
    for cfg in configurations(area):
        m = sum(v for _, v in cfg)
        d[m] = d.get(m, 0) + 1
    return d


def recursion_counts(n_max: int) -> List[int]:
    w = [1, 2, 7]
    for a in range(1, n_max - 1):
        w.append(4 * w[a + 1] - 2 * w[a])
    return w[: n_max + 1]


def main() -> None:
    n = 10
    w = recursion_counts(n)
    profiles = {a: profile(a) for a in range(n + 1)}

    print("  A | enumerated | recursion | Z(A)=D(A,0) | sum_M D^2 | Z(2A) if known")
    print("-" * 78)
    for a in range(n + 1):
        d = profiles[a]
        enumerated = sum(d.values())
        assert enumerated == w[a], f"count mismatch at A={a}"
        for m, v in d.items():
            assert d.get(-m, 0) == v, "profile is not symmetric"
            assert (m - a) % 2 == 0, "parity violated"
        sq = sum(v * v for v in d.values())
        z2a = profiles[2 * a].get(0, 0) if 2 * a <= n else None
        if z2a is not None:
            assert sq <= z2a, "concatenation injection violated"
            assert enumerated ** 2 <= (2 * a + 1) * z2a, "sharp bound violated"
        if a % 2 == 1:
            assert d.get(0, 0) == 0, "parity superselection violated"
        print(f" {a:2d} | {enumerated:10d} | {w[a]:9d} | {d.get(0,0):11d} "
              f"| {sq:9d} | {z2a if z2a is not None else '-'}")

    print()
    print("Unimodality D(A,M) <= D(A,0) fails at A = 1:")
    p1 = profiles[1]
    print(f"  D(1,+1) = {p1.get(1,0)}, D(1,0) = {p1.get(0,0)}")
    assert p1.get(1, 0) > p1.get(0, 0)
    print()
    print("All structural checks passed.")


if __name__ == "__main__":
    main()
